-- METADATA ONLY. Fill exact scoped current resource assignment/claim/review IDs.
-- Do not execute until the distinct review expressly includes this same-bounds renewal.
-- Source51471 is intentionally NOT cloned while active claim52726 executes.
BEGIN;
SET LOCAL lock_timeout='1s'; SET LOCAL statement_timeout='10s';
DO $renew$
DECLARE assignment_id bigint:=0; claim_id bigint:=0; review_id bigint:=0;
 ctl jsonb;rv jsonb;asgn jsonb;cl jsonb;pol jsonb;rec jsonb;manifest jsonb;oldacq jsonb;oldctl jsonb;
 horizon timestamptz;oper jsonb;pid bigint;rid bigint;eid bigint;restarts int;held_task text;held_attempt text;held_lease text;
BEGIN
 IF assignment_id<=0 OR claim_id<=0 OR review_id<=0 THEN RAISE EXCEPTION 'EXACT_CURRENT_SCOPED_RESOURCE_IDS_REQUIRED';END IF;
 IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RAISE EXCEPTION 'NATURAL_QUIET_CONTROLLER_BUSY';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE outcome='RUNNING') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'NATURAL_QUIET_REQUIRED';END IF;
 PERFORM 1 FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton FOR UPDATE;
 PERFORM 1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton FOR UPDATE;
 ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT details INTO STRICT asgn FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=assignment_id AND event IN('ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5','ENGINEERING_CLEARING_ASSIGNMENT_V6');
 SELECT details INTO STRICT cl FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=claim_id AND event IN('ENGINEERING_ASSIGNMENT_CLAIMED_V5','ENGINEERING_CLEARING_CLAIMED_V6');
 IF cl->>'executor' IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR cl->>'assignment_event_id' IS DISTINCT FROM assignment_id::text OR coalesce(cl->>'expires_at',cl->>'claim_expires_at') IS NULL OR coalesce(cl->>'expires_at',cl->>'claim_expires_at')::timestamptz<=clock_timestamp() OR asgn->>'owner_id' IS DISTINCT FROM ctl->>'owner_id' OR asgn->>'scope_sha256' IS DISTINCT FROM ctl->>'scope_sha256' OR asgn->>'owner_fence' IS DISTINCT FROM '3' OR asgn->>'stop_generation' IS DISTINCT FROM '1' OR asgn->>'authority_event_id' IS DISTINCT FROM '9528' THEN RAISE EXCEPTION 'EXACT_CURRENT_RESOURCE_CLAIM_REQUIRED';END IF;
 SELECT details INTO STRICT rv FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=review_id AND event='REF01_RESOURCE_TIME_METADATA_INDEPENDENT_REVIEW_V5';
 IF rv->>'approved' IS DISTINCT FROM 'true' OR rv->>'assignment_event_id' IS DISTINCT FROM assignment_id::text OR rv->>'claim_event_id' IS DISTINCT FROM claim_id::text OR rv->>'producer' IS DISTINCT FROM 'delegated-agent:/root/renewal0300' OR rv->>'reviewer' IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR rv->>'same_bounds_policy_recovery_time_renewal_explicitly_in_scope' IS DISTINCT FROM 'true' OR rv->>'prior_policy_event_id' IS DISTINCT FROM '47213' OR rv->>'prior_recovery_event_id' IS DISTINCT FROM '51089' OR rv->>'operational_admission_review_event_id' IS DISTINCT FROM '52206' OR rv->>'no_source_admission' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'DISTINCT_EXPLICIT_METADATA_SCOPE_REVIEW_REQUIRED';END IF;
 SELECT admitted_until,to_jsonb(a) INTO horizon,oldacq FROM population_top3000_202608_202609_v1.acquisition_control a WHERE singleton;
 SELECT to_jsonb(p) INTO oldctl FROM population_top3000_202608_202609_v1.pipeline_control p WHERE singleton;
 SELECT details INTO STRICT oper FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=52206 AND event='CONTINUATION_TIME_ADMISSION_REVIEWED_V6';
 IF horizon<='2026-10-25T03:18:02.923596Z'::timestamptz OR abs(extract(epoch FROM (horizon-(oper->>'new_admitted_until')::timestamptz)))>=1 OR horizon>clock_timestamp()+interval '3hours' OR horizon>(SELECT deadline FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton) OR oper->>'owner_id' IS DISTINCT FROM ctl->>'owner_id' OR oper->>'owner_fence' IS DISTINCT FROM '3' OR oper->>'stop_generation' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'ACTUAL_INSTALLED_FINITE52206_ADMISSION_REQUIRED';END IF;
 manifest:=population_top3000_202608_202609_v1.population_recovery_manifest_v1();
 IF manifest IS DISTINCT FROM '{"functions":"78bba2a9159ddec989fc338c6998972dcb4cb4c02dcd0a6fe098ad802cbe79ba","adapters":"caccf5f74fc2e567f594b5b6ab7d17fb98083082cce5d630121ece4d53adc40a"}'::jsonb OR rv->'code_manifest' IS DISTINCT FROM manifest THEN RAISE EXCEPTION 'CURRENT_REVIEWED_MANIFEST_REQUIRED';END IF;
 SELECT event_id,details INTO pid,pol FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='REF01_DATE_DISJOINT_TURN_POLICY_V10' ORDER BY event_id DESC LIMIT 1;
 SELECT event_id,details INTO rid,rec FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RECOVERY_DELEGATION_QUALIFIED_V1' ORDER BY event_id DESC LIMIT 1;
 IF pid<>47213 OR rid<>51089 OR rec->'code_manifest' IS DISTINCT FROM manifest OR rec->>'max_restarts' IS DISTINCT FROM '3' OR rec->>'cooldown_minutes' IS DISTINCT FROM '10' OR pol->>'max_provider_calls' IS DISTINCT FROM '1200' OR pol->>'max_http_invocations' IS DISTINCT FROM '1200' OR pol->>'max_source_bytes' IS DISTINCT FROM '300000000' OR pol->>'max_relation_bytes' IS DISTINCT FROM '3000000000' OR pol->'allowed_dates' IS DISTINCT FROM '["2026-09-23","2026-09-24","2026-09-25","2026-09-26","2026-09-27","2026-09-28","2026-09-29","2026-09-30"]'::jsonb THEN RAISE EXCEPTION 'EXACT_CURRENT_SAME_BOUNDS_PREIMAGES_REQUIRED';END IF;
 IF encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ref01_date_continue_impl_v10(text,bigint,bigint)'::regprocedure),'UTF8')),'hex') IS DISTINCT FROM pol->>'function_sha256' THEN RAISE EXCEPTION 'CURRENT_DATE_IMPLEMENTATION_HASH_REQUIRED';END IF;
 IF encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ref01_date_continue_v9(text,bigint,bigint)'::regprocedure),'UTF8')),'hex') IS DISTINCT FROM pol->>'wrapper_sha256' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_date_plan_v9 p WHERE p.plan_id='ref01-date-fullperiod-v9' AND p.enabled AND p.content_sha256=pol->>'plan_sha256' AND p.content_sha256=encode(sha256(convert_to(p.content::text,'UTF8')),'hex') AND p.code_bundle_sha256=population_top3000_202608_202609_v1.ref01_date_bundle_v4() AND p.content->>'max_provider_calls'=pol->>'max_provider_calls' AND p.content->>'max_http_invocations'=pol->>'max_http_invocations' AND p.content->>'max_source_bytes'=pol->>'max_source_bytes' AND p.content->>'max_relation_bytes'=pol->>'max_relation_bytes') THEN RAISE EXCEPTION 'CURRENT_DATE_WRAPPER_PLAN_AND_FINITE_BOUNDS_REQUIRED';END IF;
 SELECT encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') INTO held_task FROM population_top3000_202608_202609_v1.pipeline_task t WHERE task_id='15a87469-6335-4bf6-b883-6c86315418e7';
 SELECT encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex') INTO held_attempt FROM population_top3000_202608_202609_v1.pipeline_attempt a WHERE attempt_id='45f6e6a5-3886-4b33-b9dc-00851c1a6b04';
 SELECT encode(sha256(convert_to(to_jsonb(l)::text,'UTF8')),'hex') INTO held_lease FROM population_top3000_202608_202609_v1.pipeline_provider_lease l WHERE attempt_id='45f6e6a5-3886-4b33-b9dc-00851c1a6b04';
 IF held_task IS DISTINCT FROM pol->>'deferred_task_sha256' OR held_attempt IS DISTINCT FROM pol->>'deferred_attempt_sha256' OR held_lease IS DISTINCT FROM pol->>'deferred_lease_sha256' THEN RAISE EXCEPTION 'SEP22_IMMUTABLE_HELD_PREIMAGES_REQUIRED';END IF;
 SELECT count(*) INTO restarts FROM population_top3000_202608_202609_v1.pipeline_event e LEFT JOIN population_top3000_202608_202609_v1.pipeline_event q ON q.event_id::text=e.details->>'policy_event_id' WHERE e.event='RECOVERY_WAKE_COMPLETED_V1' AND (e.details->>'policy_event_id'='51089' OR q.details->>'authority_event_id'='9528');
 IF restarts<>0 OR rec->>'restarts_already_used_under_authority' IS DISTINCT FROM '0' THEN RAISE EXCEPTION 'CUMULATIVE_RESTART_HISTORY_ADVANCED_REVIEW_REQUIRED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('REF01_DATE_DISJOINT_TURN_POLICY_V10',pol||jsonb_build_object('producer','delegated-agent:/root/renewal0300','reviewer','automation:6adc2c96db348191bca7cf4eacfdac32','not_after',horizon,'prior_not_after',pol->'not_after','superseded_policy_event_id',47213,'assignment_event_id',assignment_id,'claim_event_id',claim_id,'independent_review_event_id',review_id,'operational_admission_review_event_id',52206,'renewal_only',true,'source_limits_unchanged',true,'uncertain_task_retry_or_release_authorized',false)) RETURNING event_id INTO pid;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RECOVERY_DELEGATION_QUALIFIED_V1',rec||jsonb_build_object('actor','automation:6adc2c96db348191bca7cf4eacfdac32','not_after',horizon,'expires_at',horizon,'requalified_at',clock_timestamp(),'superseded_policy_event_id',51089,'independent_review_event_id',review_id,'operational_admission_review_event_id',52206,'qualification_reason','Exact independently reviewed same-manifest finite time renewal; cumulative restart/progress clocks, original deadline and uncertain source hold preserved','policy_time_readmission_event_id',pid,'restarts_already_used_under_authority',restarts,'source_or_provider_calls_authorised',false)) RETURNING event_id INTO rid;
 IF population_top3000_202608_202609_v1.population_recovery_manifest_v1() IS DISTINCT FROM manifest OR (SELECT to_jsonb(a) FROM population_top3000_202608_202609_v1.acquisition_control a WHERE singleton) IS DISTINCT FROM oldacq OR (SELECT to_jsonb(p) FROM population_top3000_202608_202609_v1.pipeline_control p WHERE singleton) IS DISTINCT FROM oldctl THEN RAISE EXCEPTION 'METADATA_RENEWAL_CHANGED_CODE_CONTROL_OR_COUNTERS';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_POLICY_TIME_READMISSION_EFFECT_V5',ctl||jsonb_build_object('assignment_event_id',assignment_id,'claim_event_id',claim_id,'independent_review_event_id',review_id,'operational_admission_review_event_id',52206,'prior_policy_event_id',47213,'policy_successor_event_id',pid,'prior_recovery_event_id',51089,'recovery_successor_event_id',rid,'new_not_after',horizon,'source_assignment51471_unchanged',true,'source_assignment_new_claim_or_admission',false,'source_calls',0,'code_changed',false,'held_evidence_preserved',true,'cumulative_counters_and_restart_progress_clocks_preserved',true,'family_accepted',false)) RETURNING event_id INTO eid;
 RAISE NOTICE 'policy %, recovery %, effect %',pid,rid,eid;
END;$renew$;
COMMIT;
